WITH base AS (SELECT id, session_id, event_type, page, event_time, duration_sec, DATE_FORMAT(event_time, 'yyyy-MM') AS event_time_label FROM web_events WHERE event_time >= TIMESTAMP '2023-09-13 10:00:00' AND page IS NOT NULL AND duration_sec > 467) SELECT id, session_id, event_type, page, event_time, duration_sec, event_time_label, FIRST_VALUE(page) IGNORE NULLS OVER (PARTITION BY event_type ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_page, LAST_VALUE(duration_sec) IGNORE NULLS OVER (PARTITION BY event_type ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_duration_sec, SUM(duration_sec) OVER (PARTITION BY session_id, page ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec FROM base
